const uniqueSorted = (values) => [...new Set(values)].sort((a, b) => a.localeCompare(b));

export const REGIONS = uniqueSorted(peopleGroups.map((g) => g.region));

/**
 * Derived from the data, like REGIONS and countriesFor: a status only reaches
 * the dropdown when at least one record uses it. While this was a hard-coded
 * array, "Researching" stayed listed with no matching records and always led
 * to the empty state.
 */
export const STATUSES = uniqueSorted(peopleGroups.map((g) => g.status));

export function countriesFor(region) {
  const scope = region ? peopleGroups.filter((g) => g.region === region) : peopleGroups;
  return uniqueSorted(scope.map((g) => g.country));
}
